SELECT
    S.*
FROM
    (
    SELECT 
        'SW_ADAPI' ORGAO,
        HN.NOME,
        PDC.CPF_PESSOA,
        P.ID_PERFIL,
        PS.ID_SITUACAO,
        PS.NOME_SITUACAO,
        TM.ID_MOVIMENTACAO,
        TM.NOME_MOVIMENTACAO,
        'UPDATE SW_ADAPI.FUNCIONARIO_PERFIL SET ID_PERFIL = 9 WHERE ID_FUNCIONARIO_PERFIL = ' || FP.ID_FUNCIONARIO_PERFIL || ';' UPDATE_1,
        'UPDATE SW_ADAPI.FUNCIONARIO_PERFIL SET ID_MOVIMENTACAO = 3 WHERE ID_FUNCIONARIO_PERFIL = ' || FP.ID_FUNCIONARIO_PERFIL || ';' UPDATE_2,
        'UPDATE SW_ADAPI.FUNC_DESLIGAMENTO SET ID_PERFIL = 9 WHERE ID_DESLIGAMENTO = ' || FD.ID_DESLIGAMENTO || ';' UPDATE_3
    FROM
        SW_ADAPI.PESSOA_VINCULO PV
        JOIN SW_ADAPI.FUNCIONARIO F ON F.ID_PESSOA_VINCULO = PV.ID_PESSOA_VINCULO
        JOIN SW_PUBLICO.PESSOA_DOC_CPF PDC ON PDC.ID_PESSOA = PV.ID_PESSOA AND PDC.DATA_BAIXA IS NULL
        JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = PV.ID_PESSOA AND HN.DATA_FIM IS NULL
        JOIN SW_ADAPI.FUNC_DESLIGAMENTO FD ON FD.ID_FUNCIONARIO = F.ID_FUNCIONARIO
        JOIN SW_ADAPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = F.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
        JOIN SW_ADAPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
        JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
        JOIN SW_PUBLICO.RHB_PERFIL_TIPO_MOVIMENTACAO TM ON TM.ID_MOVIMENTACAO = FP.ID_MOVIMENTACAO
        JOIN CPFS O ON O.CPF = PDC.CPF_PESSOA
    WHERE
        FD.ID_ESOCIAL_MOTIVO_DESLIGAMENTO IN (51,53,54,55,1000352,1000371)

UNION ALL

SELECT 
        'SW_ADH' ORGAO,
        HN.NOME,
        PDC.CPF_PESSOA,
        P.ID_PERFIL,
        PS.ID_SITUACAO,
        PS.NOME_SITUACAO,
        TM.ID_MOVIMENTACAO,
        TM.NOME_MOVIMENTACAO,
        'UPDATE SW_ADH.FUNCIONARIO_PERFIL SET ID_PERFIL = 1000023 WHERE ID_FUNCIONARIO_PERFIL = ' || FP.ID_FUNCIONARIO_PERFIL || ';' UPDATE_1,
        'UPDATE SW_ADH.FUNCIONARIO_PERFIL SET ID_MOVIMENTACAO = 3 WHERE ID_FUNCIONARIO_PERFIL = ' || FP.ID_FUNCIONARIO_PERFIL || ';' UPDATE_2,
        'UPDATE SW_ADH.FUNC_DESLIGAMENTO SET ID_PERFIL = 1000023 WHERE ID_DESLIGAMENTO = ' || FD.ID_DESLIGAMENTO || ';' UPDATE_3
    FROM
        SW_ADH.PESSOA_VINCULO PV
        JOIN SW_ADH.FUNCIONARIO F ON F.ID_PESSOA_VINCULO = PV.ID_PESSOA_VINCULO
        JOIN SW_PUBLICO.PESSOA_DOC_CPF PDC ON PDC.ID_PESSOA = PV.ID_PESSOA AND PDC.DATA_BAIXA IS NULL
        JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = PV.ID_PESSOA AND HN.DATA_FIM IS NULL
        JOIN SW_ADH.FUNC_DESLIGAMENTO FD ON FD.ID_FUNCIONARIO = F.ID_FUNCIONARIO
        JOIN SW_ADH.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = F.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
